(593918, 61851, 245, '<td valign="top">Nice close up, and i like the deep contrast!</td>', 'Nice close up, and i like the deep contrast!', '2004-02-23 03:32:24.000000', NULL, 1),
(593921, 61837, 245, '<td valign="top">I''m going to rate this down because it feels too processed to me... it''s not emphasizing the photograpy, instread it hilights design and post-production. I like it, but I don''t think it''s entirely appropriate. :)</td>', 'I''m going to rate this down because it feels too processed to me... it''s not emphasizing the photograpy, instread it hilights design and post-production. I like it, but I don''t think it''s entirely appropriate. :)', '2004-02-23 03:35:32.000000', NULL, 1),
