(593928, 61666, 245, '<td valign="top">It''s too bad you lose a bit of the focus on the leading edge of the bottom shirt... this is really interesting, though!</td>', 'It''s too bad you lose a bit of the focus on the leading edge of the bottom shirt... this is really interesting, though!', '2004-02-23 03:40:11.000000', NULL, 1),
(593930, 61555, 245, '<td valign="top">I love the softness and color, but the framing leaves me wanting.</td>', 'I love the softness and color, but the framing leaves me wanting.', '2004-02-23 03:41:37.000000', NULL, 1),
(593932, 61743, 245, '<td valign="top">Too tweaked for my tastes, and it looks like it''s been sharpened too much, though it''s probably an illusion caused by the radical hue shift.</td>', 'Too tweaked for my tastes, and it looks like it''s been sharpened too much, though it''s probably an illusion caused by the radical hue shift.', '2004-02-23 03:42:27.000000', NULL, 1),
(593934, 61417, 245, '<td valign="top">I like the colors here, but the framing is a little bland. I would have tried moving the red/orange areas up and left by 10% or so, pulling the blue/green out of the corner and into a stronger position in the picture.</td>', 'I like the colors here, but the framing is a little bland. I would have tried moving the red/orange areas up and left by 10% or so, pulling the blue/green out of the corner and into a stronger position in the picture.', '2004-02-23 03:43:46.000000', NULL, 1),
(593936, 61806, 245, '<td valign="top">Really nice effect with the multi-colored light shining on different areas on the fork, you did a good job showing it off even more with the reflections.</td>', 'Really nice effect with the multi-colored light shining on different areas on the fork, you did a good job showing it off even more with the reflections.', '2004-02-23 03:45:28.000000', NULL, 1),
