(594038, 61333, 4543, '<td valign="top">Painting with light?  This is awesome and nice job!  Good Luck!</td>', 'Painting with light?  This is awesome and nice job!  Good Luck!', '2004-02-23 07:15:46.000000', NULL, 1),
(594040, 61675, 12802, '<td valign="top">To me this looks a little blurred.  It''s a great idea, really stands out, like the colours etc but it''s too out of focus.  It''s too shallow a DOF, a larger one would have made the whole remote control in focus.</td>', 'To me this looks a little blurred.  It''s a great idea, really stands out, like the colours etc but it''s too out of focus.  It''s too shallow a DOF, a larger one would have made the whole remote control in focus.', '2004-02-23 07:17:48.000000', NULL, 1),
(594046, 61748, 16636, '<td valign="top">I like the shadowing effect, but the image is to dark for me</td>', 'I like the shadowing effect, but the image is to dark for me', '2004-02-23 07:31:16.000000', NULL, 1),
(594048, 61335, 16478, '<td valign="top">I don''t get it</td>', 'I don''t get it', '2004-02-23 07:34:41.000000', NULL, 1),
(594063, 61829, 6999, '<td valign="top">Good depth of field - and strong graphic elements to this one; I do just feel that the halfway-to-silhouette of the fly seems a touch undecided - i''d either have lightened it or darkened it, myself. Excellent detail on the wings and the cutting of the tines.</td>', 'Good depth of field - and strong graphic elements to this one; I do just feel that the halfway-to-silhouette of the fly seems a touch undecided - i''d either have lightened it or darkened it, myself. Excellent detail on the wings and the cutting of the tines.', '2004-02-23 07:57:42.000000', NULL, 1),
(594069, 61830, 6999, '<td valign="top">Very indistinct I''m afraid - and the colours are very muddy for this kind of ''designer'' shot. To get that stop motion and brightness into these shots you almost always need good flash work, and this appears to have been pushed towards too long an exposure really, not quite fast enough to stop the motion.</td>', 'Very indistinct I''m afraid - and the colours are very muddy for this kind of ''designer'' shot. To get that stop motion and brightness into these shots you almost always need good flash work, and this appears to have been pushed towards too long an exposure really, not quite fast enough to stop the motion.', '2004-02-23 07:59:28.000000', NULL, 1),
(594074, 61587, 15920, '<td valign="top">Not sure how eatraordinary this is.  I remember being in High School.....anyway, it is extraordinary enough to stay in bounds, and I like the picture.  Nice focus and good cropping.</td>', 'Not sure how eatraordinary this is.  I remember being in High School.....anyway, it is extraordinary enough to stay in bounds, and I like the picture.  Nice focus and good cropping.', '2004-02-23 08:03:38.000000', NULL, 1),
(594079, 61735, 6999, '<td valign="top">Technically good work - though those reflections are just a touch strong and single-light source looking - a soft box would have spread them out more and given an overall ''cleaner'' appearance. I''m not a  big fan of selective de-saturation as a trick - and I don''t see a great purpose for it here: you don''t quite amange the ''extraordinary'' part of the challenge here for me - not beyond that de-saturation anyway.</td>', 'Technically good work - though those reflections are just a touch strong and single-light source looking - a soft box would have spread them out more and given an overall ''cleaner'' appearance. I''m not a  big fan of selective de-saturation as a trick - and I don''t see a great purpose for it here: you don''t quite amange the ''extraordinary'' part of the challenge here for me - not beyond that de-saturation anyway.', '2004-02-23 08:04:58.000000', NULL, 1),
(594082, 61351, 15920, '<td valign="top">Flames are overexposed, but I like the composition with the ring in the background.</td>', 'Flames are overexposed, but I like the composition with the ring in the background.', '2004-02-23 08:05:54.000000', NULL, 1),
(594088, 61659, 15920, '<td valign="top">Slightly overexposed on the fork near the handle, but I had to really look to find something to complain about.  This is a nice shot with obviously great lighting results.</td>', 'Slightly overexposed on the fork near the handle, but I had to really look to find something to complain about.  This is a nice shot with obviously great lighting results.', '2004-02-23 08:07:45.000000', NULL, 1),
(594092, 61848, 6999, '<td valign="top">Marvellously crazy - but a shame you couldn''t quite have stopped the left-hand dog. You score for idea, but for location (and really I probably mean light), and execution you also lose some. There is some good compositional balance - but in the end the brightness of the background undoes your work.</td>', 'Marvellously crazy - but a shame you couldn''t quite have stopped the left-hand dog. You score for idea, but for location (and really I probably mean light), and execution you also lose some. There is some good compositional balance - but in the end the brightness of the background undoes your work.', '2004-02-23 08:08:41.000000', NULL, 1),
(594096, 61550, 16676, '<td valign="top">Very good depiction of *the nutcracker*. Good clarity.  I''d have liked to seen shadows.</td>', 'Very good depiction of *the nutcracker*. Good clarity.  I''d have liked to seen shadows.', '2004-02-23 08:09:47.000000', NULL, 1),
(594106, 61796, 6999, '<td valign="top">Quite a good idea I think, though your execution, in a challenge that allows the full scope of editing, is poor. You need to bring the white level way up from here, at least. Something disturbs in the composition area too - perhaps that your cropping asks too much of the eye in a very regular shape - and the privileged areas appear to be between the faces, rather than including them.</td>', 'Quite a good idea I think, though your execution, in a challenge that allows the full scope of editing, is poor. You need to bring the white level way up from here, at least. Something disturbs in the composition area too - perhaps that your cropping asks too much of the eye in a very regular shape - and the privileged areas appear to be between the faces, rather than including them.', '2004-02-23 08:13:33.000000', NULL, 1),
(594112, 61645, 15920, '<td valign="top">More depth of field would have helped.</td>', 'More depth of field would have helped.', '2004-02-23 08:15:13.000000', NULL, 1),
(594114, 61734, 6999, '<td valign="top">Delicate, neat, strongly composed. Placement of the hands is clever. Entirely fitting the challenge, though it perhaps doesn''t quite make it into the ''extraordinary'' class. Strong image though.</td>', 'Delicate, neat, strongly composed. Placement of the hands is clever. Entirely fitting the challenge, though it perhaps doesn''t quite make it into the ''extraordinary'' class. Strong image though.', '2004-02-23 08:15:29.000000', NULL, 1),
(594118, 61708, 6999, '<td valign="top">Clever stuff indeed - like this very much - your placement of the focal point of those lines is very strong - so many would have tried to put this centrally.</td>', 'Clever stuff indeed - like this very much - your placement of the focal point of those lines is very strong - so many would have tried to put this centrally.', '2004-02-23 08:16:26.000000', NULL, 1),
(594130, 61742, 6999, '<td valign="top">Highly competent stock photography - with the possible minor exception of the clearly visible windows in the reflections. I don''t mean that as a detraction. You should try and sell it to them, they might well use it for an annual report or something. Not quite ''extraordinary'' enough for me, but solid shooting.</td>', 'Highly competent stock photography - with the possible minor exception of the clearly visible windows in the reflections. I don''t mean that as a detraction. You should try and sell it to them, they might well use it for an annual report or something. Not quite ''extraordinary'' enough for me, but solid shooting.', '2004-02-23 08:23:46.000000', NULL, 1),
(594133, 61720, 6999, '<td valign="top">I think this perhaps loses out onnlack of any idea of what ''mundane'' thing this is exactly. Light trails are good - but I can''t find anything that really suggests an idea of contact with reality.</td>', 'I think this perhaps loses out onnlack of any idea of what ''mundane'' thing this is exactly. Light trails are good - but I can''t find anything that really suggests an idea of contact with reality.', '2004-02-23 08:25:22.000000', NULL, 1),
(594138, 61719, 10167, '<td valign="top">Don''t know what it is, but I like it!</td>', 'Don''t know what it is, but I like it!', '2004-02-23 08:26:41.000000', NULL, 1),
(594144, 61782, 6999, '<td valign="top">I think your chosen depth of field actually works against this image: i don''t seen the real benefit of stressing those particular angles of the flaps against the rest of the box. Sure, the text is ;egible, but as a point that would stand out against the regularity of the rest of the box, I don''t think it neededd to be accentuated this way - for me, it only leaves the rest of the image to seem odd, as opposed to ''extraordinary''.</td>', 'I think your chosen depth of field actually works against this image: i don''t seen the real benefit of stressing those particular angles of the flaps against the rest of the box. Sure, the text is ;egible, but as a point that would stand out against the regularity of the rest of the box, I don''t think it neededd to be accentuated this way - for me, it only leaves the rest of the image to seem odd, as opposed to ''extraordinary''.', '2004-02-23 08:28:29.000000', NULL, 1),
(594160, 61711, 772, '<td valign="top">excellent work :)  I wouldn''t change a thing about this one.  The splash of red here really works nicely... great shot :)</td>', 'excellent work :)  I wouldn''t change a thing about this one.  The splash of red here really works nicely... great shot :)', '2004-02-23 08:54:22.000000', NULL, 1),
(594170, 61838, 2130, '<td valign="top">we all love Ron :)</td>', 'we all love Ron :)', '2004-02-23 09:05:16.000000', NULL, 1),
(594172, 61851, 2130, '<td valign="top">simple and strong...the lighting is great...congrats on a job well done... a 10 from me</td>', 'simple and strong...the lighting is great...congrats on a job well done... a 10 from me', '2004-02-23 09:06:37.000000', NULL, 1),
(594176, 61857, 16850, '<td valign="top">Nice composition and contrasting colors.</td>', 'Nice composition and contrasting colors.', '2004-02-23 09:13:51.000000', NULL, 1),
(594183, 61861, 16850, '<td valign="top">I''d like to see just a tad more front fill. Nice focus &amp; DOF control</td>', 'I''d like to see just a tad more front fill. Nice focus & DOF control', '2004-02-23 09:16:41.000000', NULL, 1),
(594186, 61417, 16850, '<td valign="top">I understand it, just not my style. I do like the color.</td>', 'I understand it, just not my style. I do like the color.', '2004-02-23 09:18:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(594187, 61750, 16850, '<td valign="top">I have six of these!</td>', 'I have six of these!', '2004-02-23 09:18:43.000000', NULL, 1),
(594189, 61795, 16850, '<td valign="top">Oh yes! Love the diagonals and color.</td>', 'Oh yes! Love the diagonals and color.', '2004-02-23 09:19:58.000000', NULL, 1),
(594191, 61666, 4285, '<td valign="top">Very creative way of making the mundane stand out. Great lighting. Very well ballanced composition. I''m wondering if less shallow DOF would be better (I find it a tiny bit distracting here). Otherwise my highest vote cast.</td>', 'Very creative way of making the mundane stand out. Great lighting. Very well ballanced composition. I''m wondering if less shallow DOF would be better (I find it a tiny bit distracting here). Otherwise my highest vote cast.', '2004-02-23 09:21:34.000000', NULL, 1),
(594192, 61782, 16850, '<td valign="top">I like the humor. Would like to see greater DOF or alternate focus point.</td>', 'I like the humor. Would like to see greater DOF or alternate focus point.', '2004-02-23 09:21:37.000000', NULL, 1),
(594194, 61743, 17388, '<td valign="top">A beautifully edited image, and a very nice FINished picture. Well done.</td>', 'A beautifully edited image, and a very nice FINished picture. Well done.', '2004-02-23 09:22:51.000000', NULL, 1),
(594196, 61451, 16850, '<td valign="top">I don''t see mundane or extraordinary.</td>', 'I don''t see mundane or extraordinary.', '2004-02-23 09:23:38.000000', NULL, 1),
