(594215, 61350, 16850, '<td valign="top">Hits the challenge right on!</td>', 'Hits the challenge right on!', '2004-02-23 09:32:36.000000', NULL, 1),
(594218, 61846, 16850, '<td valign="top">Great texture!</td>', 'Great texture!', '2004-02-23 09:33:10.000000', NULL, 1),
(594220, 61838, 4285, '<td valign="top">Relaxing in front of the tube is certainly mundane. It''s not easy to properly light or expose this type of interior scene; the light from the TV itself is probably playing havoc with the white ballance. Compositionally, if the TV was a little further away it might help. Maybe if you used less light you could have created an interesting silouette of your boots which might be less distracting.</td>', 'Relaxing in front of the tube is certainly mundane. It''s not easy to properly light or expose this type of interior scene; the light from the TV itself is probably playing havoc with the white ballance. Compositionally, if the TV was a little further away it might help. Maybe if you used less light you could have created an interesting silouette of your boots which might be less distracting.', '2004-02-23 09:33:59.000000', NULL, 1),
(594221, 61688, 16850, '<td valign="top">Love the structure here! Know the lighting is purposeful but distracts for me. The more I look at it the more I like it.</td>', 'Love the structure here! Know the lighting is purposeful but distracts for me. The more I look at it the more I like it.', '2004-02-23 09:35:13.000000', NULL, 1),
(594223, 61843, 16850, '<td valign="top">powerful compostion ;)</td>', 'powerful compostion ;)', '2004-02-23 09:35:52.000000', NULL, 1),
(594226, 60751, 16850, '<td valign="top">Yes. And the crop adds a lot.</td>', 'Yes. And the crop adds a lot.', '2004-02-23 09:36:32.000000', NULL, 1),
