(594783, 61814, 7889, '<td valign="top">Wonderful photograph, the colour is brilliant. Very nice indeed.</td>', 'Wonderful photograph, the colour is brilliant. Very nice indeed.', '2004-02-23 15:46:17.000000', NULL, 1),
(594803, 61847, 14593, '<td valign="top">The title of this photo gives it a lot of emotional appeal.....I guess taking so many pills daily would become very mundane...not to mention sad, but I look at the positive aspect that they are helping.......nice approach and composition...I also like it in black &amp; white....much more powerful</td>', 'The title of this photo gives it a lot of emotional appeal.....I guess taking so many pills daily would become very mundane...not to mention sad, but I look at the positive aspect that they are helping.......nice approach and composition...I also like it in black & white....much more powerful', '2004-02-23 16:28:41.000000', NULL, 1),
(594805, 61829, 14593, '<td valign="top">I hope you aren''t having fly for dinner.....interesting take on a different subject....very comical too.......I like it....it does have a certain " wow" about it!</td>', 'I hope you aren''t having fly for dinner.....interesting take on a different subject....very comical too.......I like it....it does have a certain " wow" about it!', '2004-02-23 16:30:35.000000', NULL, 1),
