(594834, 61796, 14593, '<td valign="top">are you saying that you are mundane?   Just joking.....this is a creative, different way to take a photo that probably would have otherwise been mundane...nice effect.....well done!</td>', 'are you saying that you are mundane?   Just joking.....this is a creative, different way to take a photo that probably would have otherwise been mundane...nice effect.....well done!', '2004-02-23 16:44:05.000000', NULL, 1),
(594837, 61758, 14603, '<td valign="top">Reminds me of the oil refinery close to me.<br/>Good backlighting effect on the clouds of steam and the moody backdrop adds another dimension to the shot.<br/>Well captured.</td>', 'Reminds me of the oil refinery close to me.Good backlighting effect on the clouds of steam and the moody backdrop adds another dimension to the shot.Well captured.', '2004-02-23 16:45:57.000000', NULL, 1),
(594841, 61373, 14593, '<td valign="top">this a very different take on a simple subject.....it really caught my eye!  I like the stark white background, and the detail in the subject.  I am giving this a high score...</td>', 'this a very different take on a simple subject.....it really caught my eye!  I like the stark white background, and the detail in the subject.  I am giving this a high score...', '2004-02-23 16:49:05.000000', NULL, 1),
(594844, 61516, 16636, '<td valign="top">great photo</td>', 'great photo', '2004-02-23 16:50:39.000000', NULL, 1),
(594845, 61600, 14593, '<td valign="top">well......as many flowers as I have photographed I''ve never applied a black &amp; white effect----now I wish I had!   I really like this.....I know many people on this site complain about flower ( and cat) photos, so you have turned the tables and made a rather mundane subject different and exciting.  Of course, I have never been one of those who shunned flower or cat photos....haha....I give this a 10 in my eyes!</td>', 'well......as many flowers as I have photographed I''ve never applied a black & white effect----now I wish I had!   I really like this.....I know many people on this site complain about flower ( and cat) photos, so you have turned the tables and made a rather mundane subject different and exciting.  Of course, I have never been one of those who shunned flower or cat photos....haha....I give this a 10 in my eyes!', '2004-02-23 16:52:45.000000', NULL, 1),
(594846, 61794, 14603, '<td valign="top">I think I`ve taken more time over this image than any other that I`ve looked at since joining DPC. It`s so fascinating.<br/>Could this ever have been called mundane ?<br/>Och, my head hurts trying to work it out :) Great picture regardless.....9</td>', 'I think I`ve taken more time over this image than any other that I`ve looked at since joining DPC. It`s so fascinating.Could this ever have been called mundane ?Och, my head hurts trying to work it out :) Great picture regardless.....9', '2004-02-23 16:53:30.000000', NULL, 1),
(594851, 61795, 14603, '<td valign="top">Simple idea made into a first class image by great use of colour and composition. One small niggle is that it`s too big for my screen and I have to scroll up and down to see the full picture. :)<br/>Good work.</td>', 'Simple idea made into a first class image by great use of colour and composition. One small niggle is that it`s too big for my screen and I have to scroll up and down to see the full picture. :)Good work.', '2004-02-23 16:58:50.000000', NULL, 1),
(594852, 61861, 16636, '<td valign="top">I liked your photo, though the piece of banana draws my eye in, I think maybe too much shadow and tilting it slightly would have worked better</td>', 'I liked your photo, though the piece of banana draws my eye in, I think maybe too much shadow and tilting it slightly would have worked better', '2004-02-23 16:59:56.000000', NULL, 1),
(594855, 61829, 14603, '<td valign="top">Horrible thought..but excellent image.....9</td>', 'Horrible thought..but excellent image.....9', '2004-02-23 17:01:55.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(594860, 61706, 14603, '<td valign="top">Fits the challenge very well..like the way it has been composed and the shafts of light on the arm and leg finish it off very well. Don`t know if you`ve had to clone around the head or not as it has a slightly artificial look but doesn`t spoil the image for me.<br/>Good work....9</td>', 'Fits the challenge very well..like the way it has been composed and the shafts of light on the arm and leg finish it off very well. Don`t know if you`ve had to clone around the head or not as it has a slightly artificial look but doesn`t spoil the image for me.Good work....9', '2004-02-23 17:06:47.000000', NULL, 1),
(594862, 61770, 327, '<td valign="top">Like this...like it a bunch. Not too crazy for the crop on the bottom but I still find it attractive. I think this is really fitting for the challenge. Good luck.</td>', 'Like this...like it a bunch. Not too crazy for the crop on the bottom but I still find it attractive. I think this is really fitting for the challenge. Good luck.', '2004-02-23 17:08:12.000000', NULL, 1),
(594863, 60818, 14603, '<td valign="top">The converging lines give this a nice abstract feel.</td>', 'The converging lines give this a nice abstract feel.', '2004-02-23 17:08:58.000000', NULL, 1),
(594865, 61373, 327, '<td valign="top">Very nice. They sure make an interesting photo. Living in Oregon I see them [Hazelnuts] all the time.....these really are unusual.<br/>I think you lighting/background choice is excellent. Nice job....good entry.</td>', 'Very nice. They sure make an interesting photo. Living in Oregon I see them [Hazelnuts] all the time.....these really are unusual.I think you lighting/background choice is excellent. Nice job....good entry.', '2004-02-23 17:10:24.000000', NULL, 1),
