(594867, 61782, 327, '<td valign="top">Really a good idea for the challenge.....but  this  appears very fuzzy/OOF. Soft filter/lens? Just doesn''t work for me on a shot of a cardboard box. Sorry, wish ya luck in the challenge.</td>', 'Really a good idea for the challenge.....but  this  appears very fuzzy/OOF. Soft filter/lens? Just doesn''t work for me on a shot of a cardboard box. Sorry, wish ya luck in the challenge.', '2004-02-23 17:14:05.000000', NULL, 1),
(594868, 61858, 327, '<td valign="top">Difficult to shoot in there.....lights/beams/tubes. Really busy. Good luck in the challenge.</td>', 'Difficult to shoot in there.....lights/beams/tubes. Really busy. Good luck in the challenge.', '2004-02-23 17:15:43.000000', NULL, 1),
(594869, 60898, 14603, '<td valign="top">I don`t know how this was done and to be honest, I don`t care. In my opinion, this image is an excellent example of what was asked for in the challenge. Taking a mundane subject and making it interesting.</td>', 'I don`t know how this was done and to be honest, I don`t care. In my opinion, this image is an excellent example of what was asked for in the challenge. Taking a mundane subject and making it interesting.', '2004-02-23 17:17:08.000000', NULL, 1),
