(594876, 60751, 327, '<td valign="top">I guess I''ll always find a window/door shot attractive....love them. This is a good one, great color and soft light. I feel as if it''s tilted...maybe my eyes. Good entry, so good luck in the challenge!!!</td>', 'I guess I''ll always find a window/door shot attractive....love them. This is a good one, great color and soft light. I feel as if it''s tilted...maybe my eyes. Good entry, so good luck in the challenge!!!', '2004-02-23 17:21:48.000000', NULL, 1),
(594877, 61696, 14603, '<td valign="top">I`ve noticed that a lot of voters don`t like the selective saturation effect...but here`s one that does and I like the clarity of the shot as well....9</td>', 'I`ve noticed that a lot of voters don`t like the selective saturation effect...but here`s one that does and I like the clarity of the shot as well....9', '2004-02-23 17:22:26.000000', NULL, 1),
