(595840, 61592, 5391, '<td valign="top">Love the use of the slow shutter speed to capture the main subject still and the others around her moving, going on with their tasks.  Creative camera work.</td>', 'Love the use of the slow shutter speed to capture the main subject still and the others around her moving, going on with their tasks.  Creative camera work.', '2004-02-24 09:54:32.000000', NULL, 1),
(595841, 61696, 10608, '<td valign="top">Stunning</td>', 'Stunning', '2004-02-24 09:56:19.000000', NULL, 1),
(595842, 61770, 5391, '<td valign="top">The contrast between the red and blue on the desaturated background make for a very nice composition.  I find myself wanting there to be more of a reason for it, however, something that ties the two together.  It leaves me wondering.  This would have been an excellent entry for the "unanswered questions" challenge a while back!</td>', 'The contrast between the red and blue on the desaturated background make for a very nice composition.  I find myself wanting there to be more of a reason for it, however, something that ties the two together.  It leaves me wondering.  This would have been an excellent entry for the "unanswered questions" challenge a while back!', '2004-02-24 09:56:22.000000', NULL, 1),
(595845, 61751, 5391, '<td valign="top">This is one of those shots that leaves me smacking myself on the forehead and doing a Homer Simpson "Doh!"...  Why didn''t I think of that????  Great work.  Any time I have that reaction to an image, it definitely deserves a 10.</td>', 'This is one of those shots that leaves me smacking myself on the forehead and doing a Homer Simpson "Doh!"...  Why didn''t I think of that????  Great work.  Any time I have that reaction to an image, it definitely deserves a 10.', '2004-02-24 09:57:38.000000', NULL, 1),
