(597764, 61814, 489, '<td valign="top">Excellent shot and subject. The warm colors behind the wood are perfect, and contrast nicely. Well done.</td>', 'Excellent shot and subject. The warm colors behind the wood are perfect, and contrast nicely. Well done.', '2004-02-25 10:46:29.000000', NULL, 1),
(597766, 61350, 489, '<td valign="top">Just an awesome sunset more like :-). Very nice shot.</td>', 'Just an awesome sunset more like :-). Very nice shot.', '2004-02-25 10:46:57.000000', NULL, 1),
(597767, 61386, 489, '<td valign="top">Very cool composition.</td>', 'Very cool composition.', '2004-02-25 10:47:35.000000', NULL, 1),
