(597829, 61578, 16004, '<td valign="top">This is really good, but it might (in my opinion) have been spectacular.  the "echo" on the left totally detracts from the beauty of the main subject, kind of wasting the really good detail and lighting you have.  I''d have liked the ball thingy to be bigger / closer in, filling the shot more.  8.</td>', 'This is really good, but it might (in my opinion) have been spectacular.  the "echo" on the left totally detracts from the beauty of the main subject, kind of wasting the really good detail and lighting you have.  I''d have liked the ball thingy to be bigger / closer in, filling the shot more.  8.', '2004-02-25 11:20:39.000000', NULL, 1),
(597848, 61771, 489, '<td valign="top">Visually appealing. Good color contrast, and a nice simple subject.</td>', 'Visually appealing. Good color contrast, and a nice simple subject.', '2004-02-25 11:32:45.000000', NULL, 1),
(597849, 61857, 489, '<td valign="top">Excellent shot. I really like the contrast between the foreground and background vases.</td>', 'Excellent shot. I really like the contrast between the foreground and background vases.', '2004-02-25 11:33:45.000000', NULL, 1),
