(598382, 61816, 2716, '<td valign="top">woo hoo.  The Wave.  got that one and 3 other.  Nice subject and lighting.  Jacko.  8</td>', 'woo hoo.  The Wave.  got that one and 3 other.  Nice subject and lighting.  Jacko.  8', '2004-02-25 16:25:21.000000', NULL, 1),
(598386, 61838, 2716, '<td valign="top">Ron Jeremy.  Rofl.  Nothing mundane about that guy.  lol  Jacko.  thanks for the chuckles.  10 Jacko.</td>', 'Ron Jeremy.  Rofl.  Nothing mundane about that guy.  lol  Jacko.  thanks for the chuckles.  10 Jacko.', '2004-02-25 16:28:44.000000', NULL, 1),
(598426, 61696, 3697, '<td valign="top">What a great shot for Mundane. Clarity and focus are second to none, and selective saturation works very well. Great job 10.</td>', 'What a great shot for Mundane. Clarity and focus are second to none, and selective saturation works very well. Great job 10.', '2004-02-25 16:55:02.000000', NULL, 1),
(598433, 61334, 3697, '<td valign="top">Great picture for a wristwatch advertisement! Out of curiosity, what did you use for lighting/background? To me, the bright color is what makes this shot a great one.</td>', 'Great picture for a wristwatch advertisement! Out of curiosity, what did you use for lighting/background? To me, the bright color is what makes this shot a great one.', '2004-02-25 16:58:26.000000', NULL, 1),
(598461, 61759, 3697, '<td valign="top">What an excellent idea for Mundane. You took an everyday boring subject and made it absolutely "pop" off my screen. I would really like to know what kind of background/lighting you used for this shot. Amazing, a definate 10.</td>', 'What an excellent idea for Mundane. You took an everyday boring subject and made it absolutely "pop" off my screen. I would really like to know what kind of background/lighting you used for this shot. Amazing, a definate 10.', '2004-02-25 17:13:30.000000', NULL, 1),
(598463, 61440, 3697, '<td valign="top">I like it, a handle from a pair of scissors is definately what I would call mundane and you made it interesting. Very well done.</td>', 'I like it, a handle from a pair of scissors is definately what I would call mundane and you made it interesting. Very well done.', '2004-02-25 17:14:12.000000', NULL, 1),
(598464, 61838, 3697, '<td valign="top">Hehe, what exactly were you watching?  :)</td>', 'Hehe, what exactly were you watching?  :)', '2004-02-25 17:14:32.000000', NULL, 1),
(598468, 61333, 3697, '<td valign="top">Wow, what incredible lighting... it gives a plain old rocking chair an incredibly eerie feeling. What exactly did you use for lighting? Definately one of the week''s best.</td>', 'Wow, what incredible lighting... it gives a plain old rocking chair an incredibly eerie feeling. What exactly did you use for lighting? Definately one of the week''s best.', '2004-02-25 17:15:51.000000', NULL, 1),
(598473, 61719, 3697, '<td valign="top">This is great, but for the life of me I can''t figure out what it is :)</td>', 'This is great, but for the life of me I can''t figure out what it is :)', '2004-02-25 17:17:12.000000', NULL, 1),
(598480, 61771, 16982, '<td valign="top">Good image, nice colours.  I can''t seem to vote for some reason but I would give this seven.</td>', 'Good image, nice colours.  I can''t seem to vote for some reason but I would give this seven.', '2004-02-25 17:18:49.000000', NULL, 1),
(598485, 61414, 16982, '<td valign="top">Nice effect, good idea!</td>', 'Nice effect, good idea!', '2004-02-25 17:20:15.000000', NULL, 1),
(598492, 61810, 16982, '<td valign="top">Very beautiful sky!</td>', 'Very beautiful sky!', '2004-02-25 17:23:38.000000', NULL, 1),
(598499, 61550, 16982, '<td valign="top">Now that is some excellent timing.</td>', 'Now that is some excellent timing.', '2004-02-25 17:24:31.000000', NULL, 1),
(598509, 61848, 8860, '<td valign="top">Excellent capture - rich with humour and character too. <br/> <br/>This is a shot which transcends conventional critique due to the sheer quality of subject. This is actually a 10 from me because it''s one of those shots that leaves questions unanswered, totally meets the challenge (bland or ordinary subjects transformed) and is utterly memorable. <br/> <br/>This is actually a superb composition.</td>', 'Excellent capture - rich with humour and character too.  This is a shot which transcends conventional critique due to the sheer quality of subject. This is actually a 10 from me because it''s one of those shots that leaves questions unanswered, totally meets the challenge (bland or ordinary subjects transformed) and is utterly memorable.  This is actually a superb composition.', '2004-02-25 17:28:32.000000', NULL, 1),
(598515, 61688, 8860, '<td valign="top">Very rich tones and good composition. Palm of left hand is a little too muted. <br/> <br/>Border is insipid and unecessary.</td>', 'Very rich tones and good composition. Palm of left hand is a little too muted.  Border is insipid and unecessary.', '2004-02-25 17:33:20.000000', NULL, 1),
(598519, 61696, 8860, '<td valign="top">Very nice, clean capture (pun intended!). Creative idea too with good composition and a smooth result. One of my favourites so far.</td>', 'Very nice, clean capture (pun intended!). Creative idea too with good composition and a smooth result. One of my favourites so far.', '2004-02-25 17:36:56.000000', NULL, 1),
(598522, 61761, 8860, '<td valign="top">Nice focus on an item that one rarely concentrates on so closely. Glare from chrome and highlight in the background are a bit intrusive.</td>', 'Nice focus on an item that one rarely concentrates on so closely. Glare from chrome and highlight in the background are a bit intrusive.', '2004-02-25 17:38:22.000000', NULL, 1),
(598525, 61310, 8860, '<td valign="top">Lovely shot - would have been good in the Silence challenge too.</td>', 'Lovely shot - would have been good in the Silence challenge too.', '2004-02-25 17:40:18.000000', NULL, 1),
(598528, 60991, 8860, '<td valign="top">Good viewpoint and lighting, but I feel myself craving absolute symmetry and centralisation. Very good nonetheless.</td>', 'Good viewpoint and lighting, but I feel myself craving absolute symmetry and centralisation. Very good nonetheless.', '2004-02-25 17:42:38.000000', NULL, 1),
(598529, 61645, 8860, '<td valign="top">Great viewpoint but just lacks that crucial focus on the eye. For what it''s worth I wouldn''t consider a parrot mundane anyway!</td>', 'Great viewpoint but just lacks that crucial focus on the eye. For what it''s worth I wouldn''t consider a parrot mundane anyway!', '2004-02-25 17:42:43.000000', NULL, 1),
(598531, 61666, 8860, '<td valign="top">Very cute.</td>', 'Very cute.', '2004-02-25 17:43:08.000000', NULL, 1),
(598536, 61422, 8860, '<td valign="top">Very interesting and striking shot. beautiful light and textures so a good choice. Clean shot too.</td>', 'Very interesting and striking shot. beautiful light and textures so a good choice. Clean shot too.', '2004-02-25 17:44:43.000000', NULL, 1),
(598538, 61550, 8860, '<td valign="top">Aaprt from your title I love this. Excellent capture with good focus. Thumb is a bit intrusive and lighting on nutcracker could be better and could have been enhanced with a bit of careful dodging.</td>', 'Aaprt from your title I love this. Excellent capture with good focus. Thumb is a bit intrusive and lighting on nutcracker could be better and could have been enhanced with a bit of careful dodging.', '2004-02-25 17:46:42.000000', NULL, 1),
(598539, 61646, 8860, '<td valign="top">Well thanks for stating the bleedin'' obvious for us all in your title! Interesting view but top highlight is very distracting.</td>', 'Well thanks for stating the bleedin'' obvious for us all in your title! Interesting view but top highlight is very distracting.', '2004-02-25 17:47:45.000000', NULL, 1),
(598540, 61711, 8860, '<td valign="top">Like the rich texture and dynamic contrast. Good composition.</td>', 'Like the rich texture and dynamic contrast. Good composition.', '2004-02-25 17:48:36.000000', NULL, 1),
(598693, 61748, 15207, '<td valign="top">I know a lot of people used forks in this challenge... but I think what sets yours apart is that you took the time to compose the shot well and you clearly thought about the lighting. I like that there''s a nice balance with your shadow. Great shot!</td>', 'I know a lot of people used forks in this challenge... but I think what sets yours apart is that you took the time to compose the shot well and you clearly thought about the lighting. I like that there''s a nice balance with your shadow. Great shot!', '2004-02-25 18:36:46.000000', NULL, 1),
(598697, 61493, 15207, '<td valign="top">I really like how you lit and composed this shot. I hope you do really well.<br/> <br/>Good luck!</td>', 'I really like how you lit and composed this shot. I hope you do really well. Good luck!', '2004-02-25 18:37:23.000000', NULL, 1),
(598717, 61518, 15207, '<td valign="top">I like this one. It''s clear you took the time to light it and compose it well. I like the details in the pen. Good luck!</td>', 'I like this one. It''s clear you took the time to light it and compose it well. I like the details in the pen. Good luck!', '2004-02-25 18:46:10.000000', NULL, 1),
(598763, 61333, 2158, '<td valign="top">I wish there was a bit more light underneath the chair.  The rest looks great.</td>', 'I wish there was a bit more light underneath the chair.  The rest looks great.', '2004-02-25 19:17:17.000000', NULL, 1),
(598899, 61652, 17377, '<td valign="top">I like the shot,  But a little bit much on the post editing.</td>', 'I like the shot,  But a little bit much on the post editing.', '2004-02-25 20:43:25.000000', NULL, 1),
(598927, 60897, 1280, '<td valign="top">Nicely done!</td>', 'Nicely done!', '2004-02-25 21:07:44.000000', NULL, 1),
(598934, 61458, 1280, '<td valign="top">Very cool!  Reminds me of an art plaque I made.  Dried beans and peas are inherently beautiful.  Good job!</td>', 'Very cool!  Reminds me of an art plaque I made.  Dried beans and peas are inherently beautiful.  Good job!', '2004-02-25 21:13:03.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
