(598968, 61748, 1280, '<td valign="top">Nice simplicity</td>', 'Nice simplicity', '2004-02-25 21:39:03.000000', NULL, 1),
(599004, 61848, 12253, '<td valign="top">Wonderful moment!  It''s a shame that you weren''t able to get as good stop action on the left as on the right.  Although it''s great to see both dogs, you might have a better photo if you crop the left out, and the setting might work better too.</td>', 'Wonderful moment!  It''s a shame that you weren''t able to get as good stop action on the left as on the right.  Although it''s great to see both dogs, you might have a better photo if you crop the left out, and the setting might work better too.', '2004-02-25 22:08:03.000000', NULL, 1),
(599011, 61310, 12253, '<td valign="top">Nice scene and view.  Might just be an illusion, but the tree branches have small halos which look like a bit of oversharpening (and see the base of the tree on the right).  I think a softer image would work here anyway (though the masses may not agree!)</td>', 'Nice scene and view.  Might just be an illusion, but the tree branches have small halos which look like a bit of oversharpening (and see the base of the tree on the right).  I think a softer image would work here anyway (though the masses may not agree!)', '2004-02-25 22:10:17.000000', NULL, 1),
(599037, 61806, 1280, '<td valign="top">Wonderful job!</td>', 'Wonderful job!', '2004-02-25 22:30:19.000000', NULL, 1),
