(600824, 61603, 4793, '<td valign="top">I love the textures and colors.</td>', 'I love the textures and colors.', '2004-02-27 00:20:20.000000', NULL, 1),
(600825, 61498, 4793, '<td valign="top">Lovely composition and colors, very nice.</td>', 'Lovely composition and colors, very nice.', '2004-02-27 00:20:56.000000', NULL, 1),
(600827, 61550, 811, '<td valign="top">Great capture.   It would have been really cool without the hand in there, though its presence does give it a stable, "anchored" feeling.</td>', 'Great capture.   It would have been really cool without the hand in there, though its presence does give it a stable, "anchored" feeling.', '2004-02-27 00:21:17.000000', NULL, 1),
(600830, 61833, 811, '<td valign="top">The window area seems slightly overexposed, but the interior is nicely lit.  I guess a different time of day would help prevent that, though that is not always do-able.</td>', 'The window area seems slightly overexposed, but the interior is nicely lit.  I guess a different time of day would help prevent that, though that is not always do-able.', '2004-02-27 00:24:46.000000', NULL, 1),
(600831, 61810, 4793, '<td valign="top">Lovely colors.</td>', 'Lovely colors.', '2004-02-27 00:27:11.000000', NULL, 1),
(600833, 61829, 811, '<td valign="top">Good composition, and the lightine looks overexposed, but it is effective, I think.</td>', 'Good composition, and the lightine looks overexposed, but it is effective, I think.', '2004-02-27 00:27:39.000000', NULL, 1),
(600835, 61349, 4793, '<td valign="top">Very nice colors and composition</td>', 'Very nice colors and composition', '2004-02-27 00:28:13.000000', NULL, 1),
(600837, 61842, 811, '<td valign="top">I think if would feel more balanced if it were in the left side of the picture with the shadow going the other way, but that is just me.  Good detail and lighting.</td>', 'I think if would feel more balanced if it were in the left side of the picture with the shadow going the other way, but that is just me.  Good detail and lighting.', '2004-02-27 00:29:40.000000', NULL, 1),
(600839, 61853, 811, '<td valign="top">I really like the red building in the background.  My eyes go from the dark part of the frame to it and back.  .</td>', 'I really like the red building in the background.  My eyes go from the dark part of the frame to it and back.  .', '2004-02-27 00:31:52.000000', NULL, 1),
(600841, 61814, 811, '<td valign="top">I think the blue coloring with the goldenish background works well.  Also, the repeated verticals make this a strong, stable shot, I think.</td>', 'I think the blue coloring with the goldenish background works well.  Also, the repeated verticals make this a strong, stable shot, I think.', '2004-02-27 00:34:26.000000', NULL, 1),
(600855, 61645, 9906, '<td valign="top">This seems to be a little soft all around.  The composition is nice and interesting though!<br/>TC</td>', 'This seems to be a little soft all around.  The composition is nice and interesting though!TC', '2004-02-27 00:58:51.000000', NULL, 1),
(600862, 61788, 9906, '<td valign="top">This IMHO has gone beyond photographic integrity into the realm of digital art and thus belongs on a different site...<br/>TC</td>', 'This IMHO has gone beyond photographic integrity into the realm of digital art and thus belongs on a different site...TC', '2004-02-27 01:26:49.000000', NULL, 1),
(600863, 61765, 9906, '<td valign="top">Now this is a cool sot of an interesting place, but to me doesn''t say mundane.  Love your framing and the natural color scheme!  There are also some interesting lines to lead you through the shot.  Nice shot but not mundane...<br/>TC</td>', 'Now this is a cool sot of an interesting place, but to me doesn''t say mundane.  Love your framing and the natural color scheme!  There are also some interesting lines to lead you through the shot.  Nice shot but not mundane...TC', '2004-02-27 01:28:46.000000', NULL, 1),
(600865, 61711, 9906, '<td valign="top">Tres cool!  Love the monotone feel with the expired flag popping out!  Good job.  My only complaint would be that the frame is not needed.<br/>TC</td>', 'Tres cool!  Love the monotone feel with the expired flag popping out!  Good job.  My only complaint would be that the frame is not needed.TC', '2004-02-27 01:30:41.000000', NULL, 1),
(600867, 60956, 9906, '<td valign="top">Excellent highe key treatment here!  Love everything except the gold pull cord.  Great job of framing.  I Even like the border in this instance!<br/>TC</td>', 'Excellent highe key treatment here!  Love everything except the gold pull cord.  Great job of framing.  I Even like the border in this instance!TC', '2004-02-27 01:38:12.000000', NULL, 1),
(600881, 61846, 9906, '<td valign="top">this looks to be very oversharpened...<br/>TC</td>', 'this looks to be very oversharpened...TC', '2004-02-27 01:57:51.000000', NULL, 1),
(600903, 61696, 4767, '<td valign="top">Mundane, indeed!  LOL</td>', 'Mundane, indeed!  LOL', '2004-02-27 02:12:46.000000', NULL, 1),
