INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(601570, 61806, 2553, '<td valign="top">I love this, but it actually would have had more of an impact on me if it had been oriented in the portrait position with the tines of the forks at the bottom.  9</td>', 'I love this, but it actually would have had more of an impact on me if it had been oriented in the portrait position with the tines of the forks at the bottom.  9', '2004-02-27 16:14:19.000000', NULL, 1),
(601572, 61334, 2553, '<td valign="top">Beautifully crisp shot with very nice colors, and perfect focus for the subject.</td>', 'Beautifully crisp shot with very nice colors, and perfect focus for the subject.', '2004-02-27 16:15:20.000000', NULL, 1),
(601574, 61095, 2553, '<td valign="top">How very imaginative!  I was blown away by this shot, it is perfect for the challenge.</td>', 'How very imaginative!  I was blown away by this shot, it is perfect for the challenge.', '2004-02-27 16:16:14.000000', NULL, 1),
(601576, 60944, 2553, '<td valign="top">Very cool shot.  DOF works well, composition is interesing and dynamic, colors are vibrant.  9</td>', 'Very cool shot.  DOF works well, composition is interesing and dynamic, colors are vibrant.  9', '2004-02-27 16:17:09.000000', NULL, 1),
(601578, 61333, 2553, '<td valign="top">Love how you''ve made an ordinary rocker into something almost spooky!  Great work with the lighting.</td>', 'Love how you''ve made an ordinary rocker into something almost spooky!  Great work with the lighting.', '2004-02-27 16:17:56.000000', NULL, 1),
(601579, 61701, 2553, '<td valign="top">I like the colors and composition, and how it is light on one side and dark on the other.  Cool shot.</td>', 'I like the colors and composition, and how it is light on one side and dark on the other.  Cool shot.', '2004-02-27 16:18:52.000000', NULL, 1),
(601599, 60783, 5982, '<td valign="top">is your glass dirty??  what are the dark spots? ImhO they destroy the potential of this photo.  Also a better contrast between the glass and the background may have help give impact.</td>', 'is your glass dirty??  what are the dark spots? ImhO they destroy the potential of this photo.  Also a better contrast between the glass and the background may have help give impact.', '2004-02-27 16:31:50.000000', NULL, 1),
(601601, 61796, 5982, '<td valign="top">how does this picture, interesting yes, makes the subject more important? I don''t understand the link between the picture and the theme.</td>', 'how does this picture, interesting yes, makes the subject more important? I don''t understand the link between the picture and the theme.', '2004-02-27 16:33:05.000000', NULL, 1),
(601614, 61701, 5982, '<td valign="top">Very nice, it would have been perfect if the left side would have been also in focus.  Nice idea.</td>', 'Very nice, it would have been perfect if the left side would have been also in focus.  Nice idea.', '2004-02-27 16:39:49.000000', NULL, 1),
(601630, 61742, 3697, '<td valign="top">Good color and I like your use of DOF. Also, tilting the composition like you did raised this from a boring, run of the mill shot to something more :)</td>', 'Good color and I like your use of DOF. Also, tilting the composition like you did raised this from a boring, run of the mill shot to something more :)', '2004-02-27 16:51:26.000000', NULL, 1),
(601634, 61557, 3697, '<td valign="top">Wow, this is great... definately a mundane subject that pops right off my screen! The subtle differences in texture between the floor, chair, and bread is what makes this an excellent photo IMO.</td>', 'Wow, this is great... definately a mundane subject that pops right off my screen! The subtle differences in texture between the floor, chair, and bread is what makes this an excellent photo IMO.', '2004-02-27 16:53:54.000000', NULL, 1),
(601638, 61701, 3697, '<td valign="top">Very interesting approach using he gradient "light to dark" lighting. I like it :)</td>', 'Very interesting approach using he gradient "light to dark" lighting. I like it :)', '2004-02-27 16:55:13.000000', NULL, 1),
(601641, 61604, 3697, '<td valign="top">Great idea for this week''s challenge! The black and white contrasts very well with the rust color of the nail, and the fact that the nail is bent over is also a plus in my eyes. The only thing I can think that might be improved is the darkness in the bottom, left corner. A solid 8.</td>', 'Great idea for this week''s challenge! The black and white contrasts very well with the rust color of the nail, and the fact that the nail is bent over is also a plus in my eyes. The only thing I can think that might be improved is the darkness in the bottom, left corner. A solid 8.', '2004-02-27 16:56:23.000000', NULL, 1),
(601644, 61652, 3697, '<td valign="top">This is definately the most creative approach to this week''s assignment, in my opinion.  :)  Great background and focus, and I especially like the focus blurs and the  "laser fire". Good work.</td>', 'This is definately the most creative approach to this week''s assignment, in my opinion.  :)  Great background and focus, and I especially like the focus blurs and the  "laser fire". Good work.', '2004-02-27 16:58:07.000000', NULL, 1),
(601646, 61646, 3697, '<td valign="top">Now THAT is some tack sharp focus on the water drop... nicely captured.</td>', 'Now THAT is some tack sharp focus on the water drop... nicely captured.', '2004-02-27 16:59:26.000000', NULL, 1),
(601665, 61666, 10819, '<td valign="top">this is the neatest fold i have ever seen!!!very cool.</td>', 'this is the neatest fold i have ever seen!!!very cool.', '2004-02-27 17:16:21.000000', NULL, 1),
(601716, 60944, 12475, '<td valign="top">Gorgeous color (I like the egg-yolk-yellow of the center of the whisk). This meets the challenge perfectly, IMHO.</td>', 'Gorgeous color (I like the egg-yolk-yellow of the center of the whisk). This meets the challenge perfectly, IMHO.', '2004-02-27 17:54:10.000000', NULL, 1),
(601799, 61700, 12253, '<td valign="top">Excellent pattern and abstract shot!  For the final you might consider cloning out some of the bigger sparkles on the left which look almost like dust (and equally distracting!)  What is the shadow from?</td>', 'Excellent pattern and abstract shot!  For the final you might consider cloning out some of the bigger sparkles on the left which look almost like dust (and equally distracting!)  What is the shadow from?', '2004-02-27 18:58:07.000000', NULL, 1),
(601800, 61741, 12253, '<td valign="top">Simple but very elegant!</td>', 'Simple but very elegant!', '2004-02-27 18:58:24.000000', NULL, 1),
(601801, 61686, 12253, '<td valign="top">Great catch!  Now look out!</td>', 'Great catch!  Now look out!', '2004-02-27 18:58:38.000000', NULL, 1),
(601806, 61719, 12253, '<td valign="top">Nice unique perspective and shot.  A cloudy day without the bright sun in the frame might have been a bit better.</td>', 'Nice unique perspective and shot.  A cloudy day without the bright sun in the frame might have been a bit better.', '2004-02-27 19:01:10.000000', NULL, 1),
