(602216, 61228, 12160, '<td valign="top">Nice clear focus on the eyes. Well-done on exposure. 7</td>', 'Nice clear focus on the eyes. Well-done on exposure. 7', '2004-02-28 07:04:53.000000', NULL, 1),
