(603000, 60751, 15606, '<td valign="top">the very nice thing about this is the light emphasizing the subtle designs in the curtain - however, it doesn''t quite get there enough.  Just a touch more exposure, or perhaps a little post processing to increase the contrast of the designs would help.  Keep looking for that light :)</td>', 'the very nice thing about this is the light emphasizing the subtle designs in the curtain - however, it doesn''t quite get there enough.  Just a touch more exposure, or perhaps a little post processing to increase the contrast of the designs would help.  Keep looking for that light :)', '2004-02-28 19:51:36.000000', NULL, 1),
(603003, 61737, 15606, '<td valign="top">I might try a tighter crop to reduce the distracting patterns in the spread and the wallpaper, but other than that, this is quite nice.  Your taco bell doggie looks quite classic.</td>', 'I might try a tighter crop to reduce the distracting patterns in the spread and the wallpaper, but other than that, this is quite nice.  Your taco bell doggie looks quite classic.', '2004-02-28 19:54:12.000000', NULL, 1),
(603004, 61440, 15606, '<td valign="top">bold, simple, eye catching, curvy, contrasty - I yike it!</td>', 'bold, simple, eye catching, curvy, contrasty - I yike it!', '2004-02-28 19:54:47.000000', NULL, 1),
(603008, 61516, 15606, '<td valign="top">Nice color, and I love the way you''ve cought the flow of their tails.  I might have cloned out the gunky stuff in the water, but that''s me.</td>', 'Nice color, and I love the way you''ve cought the flow of their tails.  I might have cloned out the gunky stuff in the water, but that''s me.', '2004-02-28 19:57:09.000000', NULL, 1),
(603009, 61493, 15606, '<td valign="top">nice negative space - I''m sure it was tough to get that chair lighted well, but I think it still has a little too much light around on the ground.</td>', 'nice negative space - I''m sure it was tough to get that chair lighted well, but I think it still has a little too much light around on the ground.', '2004-02-28 19:59:45.000000', NULL, 1),
(603011, 61700, 15606, '<td valign="top">I thought this was skin - like multiple belly buttons when I first saw it!  very interesting,</td>', 'I thought this was skin - like multiple belly buttons when I first saw it!  very interesting,', '2004-02-28 20:01:52.000000', NULL, 1),
(603012, 61557, 15606, '<td valign="top">very nice tones - the layering works very well to make each ordinarily bland texture stand out</td>', 'very nice tones - the layering works very well to make each ordinarily bland texture stand out', '2004-02-28 20:03:39.000000', NULL, 1),
(603015, 61686, 15606, '<td valign="top">wheee!  very fun picture!</td>', 'wheee!  very fun picture!', '2004-02-28 20:04:02.000000', NULL, 1),
(603016, 61751, 15606, '<td valign="top">This is what this contest is all about.  How cool is this???   And how ever were you so incredibly patient to arrange all those rubber bands so evenly??  This needs to be one of those motivational posters - very nice job! 10</td>', 'This is what this contest is all about.  How cool is this???   And how ever were you so incredibly patient to arrange all those rubber bands so evenly??  This needs to be one of those motivational posters - very nice job! 10', '2004-02-28 20:05:36.000000', NULL, 1),
(603018, 61758, 15606, '<td valign="top">very cool image - so much to look at. The ridge in the background is just such a wonderful unexpected surprise.</td>', 'very cool image - so much to look at. The ridge in the background is just such a wonderful unexpected surprise.', '2004-02-28 20:07:29.000000', NULL, 1),
(603019, 61648, 15606, '<td valign="top">this is absolutely lovely.  You''ve managed to turn this dull dock into an echo of japanese art, and the tones you chose simply enchance the delicacy you''ve uncovered.  bravo.</td>', 'this is absolutely lovely.  You''ve managed to turn this dull dock into an echo of japanese art, and the tones you chose simply enchance the delicacy you''ve uncovered.  bravo.', '2004-02-28 20:09:47.000000', NULL, 1),
(603020, 61728, 15606, '<td valign="top">this is a perfect example where the title makes the shot!  cute cute cute!</td>', 'this is a perfect example where the title makes the shot!  cute cute cute!', '2004-02-28 20:10:53.000000', NULL, 1),
(603021, 61860, 15606, '<td valign="top">normally, I''m not a huge fan of grain, but I think this image could use a little.  It seems so clean compared to the street scene it''s portraying.  almost sterile.</td>', 'normally, I''m not a huge fan of grain, but I think this image could use a little.  It seems so clean compared to the street scene it''s portraying.  almost sterile.', '2004-02-28 20:12:19.000000', NULL, 1),
(603022, 61696, 15606, '<td valign="top">heh.  nice work.</td>', 'heh.  nice work.', '2004-02-28 20:12:42.000000', NULL, 1),
(603024, 61377, 15606, '<td valign="top">wonderful!  the glowing blue is set off even better by the subtle green and pink.  very nice composition and color and lighting.  My only nit is that the green seems to be a bit askew, but very minor issue.</td>', 'wonderful!  the glowing blue is set off even better by the subtle green and pink.  very nice composition and color and lighting.  My only nit is that the green seems to be a bit askew, but very minor issue.', '2004-02-28 20:14:40.000000', NULL, 1),
(603025, 61537, 15606, '<td valign="top">yummy gold</td>', 'yummy gold', '2004-02-28 20:15:11.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(603026, 61731, 5391, '<td valign="top">I absolutely love the monochrome feel to this, and the way the background really enhances the sharpenss of those barbs.  Excellent shot.  I''m inspired to try something like it, myself.  Perfectly fitting the challenge as well.  9</td>', 'I absolutely love the monochrome feel to this, and the way the background really enhances the sharpenss of those barbs.  Excellent shot.  I''m inspired to try something like it, myself.  Perfectly fitting the challenge as well.  9', '2004-02-28 20:15:45.000000', NULL, 1),
(603027, 61806, 15606, '<td valign="top">delicious lighting.  I hope you give it up in your image description how you did it.</td>', 'delicious lighting.  I hope you give it up in your image description how you did it.', '2004-02-28 20:15:52.000000', NULL, 1),
(603028, 61840, 15606, '<td valign="top">Whoa!  This gives me the willies!  nice impact.</td>', 'Whoa!  This gives me the willies!  nice impact.', '2004-02-28 20:16:16.000000', NULL, 1),
(603030, 61758, 5391, '<td valign="top">A beautiful shot and perhaps one of the most unusual of the challenge.  My husband works for a plant that has towers of steam that rise up like this, and I''m always thinking how I''d like to photograph them.  Great to turn industry into something beautiful.  Love the color scheme and the composition.  Just can''t find anything wrong with this!  10</td>', 'A beautiful shot and perhaps one of the most unusual of the challenge.  My husband works for a plant that has towers of steam that rise up like this, and I''m always thinking how I''d like to photograph them.  Great to turn industry into something beautiful.  Love the color scheme and the composition.  Just can''t find anything wrong with this!  10', '2004-02-28 20:17:14.000000', NULL, 1),
(603031, 61854, 5391, '<td valign="top">Lots of forks in this challenge, but this one stands out to me as the best.  Great lighting to really make those forks stand out against the background darkness.  I''m perhaps a little bothered by the one that goes straight across the center of the image - I think it detracts from the dynamism of the photograph as a whole, but still overall a very good shot.  8</td>', 'Lots of forks in this challenge, but this one stands out to me as the best.  Great lighting to really make those forks stand out against the background darkness.  I''m perhaps a little bothered by the one that goes straight across the center of the image - I think it detracts from the dynamism of the photograph as a whole, but still overall a very good shot.  8', '2004-02-28 20:18:41.000000', NULL, 1),
(603032, 61529, 5391, '<td valign="top">Perhaps THE most mundane object photographed in the challenge.  You''ve done a great job.  I love the sharpness of those loops of terry cloth and the overall "feeling" of laundry and softness that the whole image has.  8</td>', 'Perhaps THE most mundane object photographed in the challenge.  You''ve done a great job.  I love the sharpness of those loops of terry cloth and the overall "feeling" of laundry and softness that the whole image has.  8', '2004-02-28 20:20:04.000000', NULL, 1),
(603034, 61589, 5391, '<td valign="top">This is really a heart-warming image to me.  The sweet look on the animal''s face, along with that sweet bit of greenery hanging out of its mouth, as if it''s chewing on it thoughtfully, as a person might chew on a stalk of grass, really makes the viewer feel connected to the subject.  The diagonal lines in the landscape add a strong dynamic to the image, and the absence of almost any bright color other than green really gives this impact as well.  I''ve gone back and forth trying to decide on a score for this, and I''ve decided overall it''s a 9.  I hope others appreciate the beauty of this "mundane" creature you''ve captured as I do.</td>', 'This is really a heart-warming image to me.  The sweet look on the animal''s face, along with that sweet bit of greenery hanging out of its mouth, as if it''s chewing on it thoughtfully, as a person might chew on a stalk of grass, really makes the viewer feel connected to the subject.  The diagonal lines in the landscape add a strong dynamic to the image, and the absence of almost any bright color other than green really gives this impact as well.  I''ve gone back and forth trying to decide on a score for this, and I''ve decided overall it''s a 9.  I hope others appreciate the beauty of this "mundane" creature you''ve captured as I do.', '2004-02-28 20:23:17.000000', NULL, 1),
(603035, 61586, 5391, '<td valign="top">Interesting abstract, well seen.  I''m a tiny bit distracted by the somewhat uneven lighting, but I''m a big fan of graphic abstract images and like this very much.</td>', 'Interesting abstract, well seen.  I''m a tiny bit distracted by the somewhat uneven lighting, but I''m a big fan of graphic abstract images and like this very much.', '2004-02-28 20:24:47.000000', NULL, 1),
(603047, 61552, 15606, '<td valign="top">love the joyful feeling - like the stapler is jumping for joy</td>', 'love the joyful feeling - like the stapler is jumping for joy', '2004-02-28 20:33:53.000000', NULL, 1),
(603051, 61474, 15606, '<td valign="top">interesting to take it outside :)</td>', 'interesting to take it outside :)', '2004-02-28 20:36:45.000000', NULL, 1),
(603052, 61848, 10084, '<td valign="top">Kind of funny that both dogs are jumping and that you were able to capture them at the same height. Having 1 of the dogs blurred gives a sense of motion.</td>', 'Kind of funny that both dogs are jumping and that you were able to capture them at the same height. Having 1 of the dogs blurred gives a sense of motion.', '2004-02-28 20:37:33.000000', NULL, 1),
(603053, 61600, 15606, '<td valign="top">yummy DOF, nice job on the b/w</td>', 'yummy DOF, nice job on the b/w', '2004-02-28 20:38:41.000000', NULL, 1),
(603054, 61859, 10084, '<td valign="top">Vibrant hues and the dark background really makes the red/orange/yellow pop out of the shot. Would like to see a focal point to keep interest on the composition.</td>', 'Vibrant hues and the dark background really makes the red/orange/yellow pop out of the shot. Would like to see a focal point to keep interest on the composition.', '2004-02-28 20:39:04.000000', NULL, 1),
(603056, 61095, 15606, '<td valign="top">Scrumptious!</td>', 'Scrumptious!', '2004-02-28 20:39:47.000000', NULL, 1),
(603058, 61837, 10084, '<td valign="top">Interesting abstract composition. It''s one of those shots that you have to step back to really enjoy. Up close you look at the small parts but when you step back you can see the whole picture. Very graphic. I interesting idea.</td>', 'Interesting abstract composition. It''s one of those shots that you have to step back to really enjoy. Up close you look at the small parts but when you step back you can see the whole picture. Very graphic. I interesting idea.', '2004-02-28 20:40:54.000000', NULL, 1),
(603059, 61335, 15606, '<td valign="top">don''t nomally go in for these kinds of borders, but it looks very pastoral this way - nice</td>', 'don''t nomally go in for these kinds of borders, but it looks very pastoral this way - nice', '2004-02-28 20:44:09.000000', NULL, 1),
(603060, 61379, 10084, '<td valign="top">Would like to see less negative space. Cropping closer would really give the viewer a better focus on the subject. Very creative idea arranged to make the subject very interesting. "8"</td>', 'Would like to see less negative space. Cropping closer would really give the viewer a better focus on the subject. Very creative idea arranged to make the subject very interesting. "8"', '2004-02-28 20:44:24.000000', NULL, 1),
(603062, 61451, 15606, '<td valign="top">cool - looks like an eye</td>', 'cool - looks like an eye', '2004-02-28 20:45:45.000000', NULL, 1),
(603063, 60944, 15606, '<td valign="top">wow, really jumps out at ya!  very cool!</td>', 'wow, really jumps out at ya!  very cool!', '2004-02-28 20:47:03.000000', NULL, 1),
(603065, 61719, 10084, '<td valign="top">Very interesting view. I like how the slope in the background makes the scene seem more like a landscape. The repetition of the circular objects gives a great feeling of harmony. Was "9" moving to "10"</td>', 'Very interesting view. I like how the slope in the background makes the scene seem more like a landscape. The repetition of the circular objects gives a great feeling of harmony. Was "9" moving to "10"', '2004-02-28 20:49:16.000000', NULL, 1),
(603066, 61652, 15606, '<td valign="top">this is too hilarious!  nice job</td>', 'this is too hilarious!  nice job', '2004-02-28 20:50:03.000000', NULL, 1),
(603067, 61731, 10818, '<td valign="top">Fantastic shot, love the blueish color, and fits the theme vey well.</td>', 'Fantastic shot, love the blueish color, and fits the theme vey well.', '2004-02-28 20:50:41.000000', NULL, 1),
(603068, 60987, 6349, '<td valign="top">oh yeah, this is a very interesting take on the challenge.  how many licks does it take to get to the center etc...</td>', 'oh yeah, this is a very interesting take on the challenge.  how many licks does it take to get to the center etc...', '2004-02-28 20:50:49.000000', NULL, 1),
(603069, 61719, 15606, '<td valign="top">COOL! Nothing but COOL!</td>', 'COOL! Nothing but COOL!', '2004-02-28 20:51:29.000000', NULL, 1),
(603070, 61592, 6349, '<td valign="top">great image.  you really captured the feeling of being bored at work, a very mundane thing indeed.  The fact that everybody else is in motion and the girl is still looking at the clock make this extraordinary.  10</td>', 'great image.  you really captured the feeling of being bored at work, a very mundane thing indeed.  The fact that everybody else is in motion and the girl is still looking at the clock make this extraordinary.  10', '2004-02-28 20:54:37.000000', NULL, 1),
(603071, 61853, 6349, '<td valign="top">interesting.</td>', 'interesting.', '2004-02-28 20:55:34.000000', NULL, 1),
(603073, 61711, 6349, '<td valign="top">Love it 10</td>', 'Love it 10', '2004-02-28 20:56:08.000000', NULL, 1),
(603074, 61498, 6349, '<td valign="top">cool idea</td>', 'cool idea', '2004-02-28 20:57:06.000000', NULL, 1),
(603075, 61550, 6349, '<td valign="top">I just did this today.  Great shot.  One of my favorites so far. 10</td>', 'I just did this today.  Great shot.  One of my favorites so far. 10', '2004-02-28 20:57:44.000000', NULL, 1),
(603076, 60931, 6349, '<td valign="top">very nice.  hope nobody tells you your snow should be whiter.  it shouldn''t.</td>', 'very nice.  hope nobody tells you your snow should be whiter.  it shouldn''t.', '2004-02-28 20:58:14.000000', NULL, 1),
(603077, 61560, 6349, '<td valign="top">m....very nice.  I like that you''ve broken the stupid rules and put the horizon so low but I''d still get rid of a bit of the sky.</td>', 'm....very nice.  I like that you''ve broken the stupid rules and put the horizon so low but I''d still get rid of a bit of the sky.', '2004-02-28 21:00:10.000000', NULL, 1),
(603078, 61728, 6349, '<td valign="top">hahahahahaha.  great.  highlights are a little harsh.  wish they didn''t appear to be floating (although they are starting to look like aliens floating in space the more I look at it)</td>', 'hahahahahaha.  great.  highlights are a little harsh.  wish they didn''t appear to be floating (although they are starting to look like aliens floating in space the more I look at it)', '2004-02-28 21:03:04.000000', NULL, 1),
(603080, 61686, 6349, '<td valign="top">This is great.  DId you do it?  Looking forward to finding out.  This should do very well in the challenge.</td>', 'This is great.  DId you do it?  Looking forward to finding out.  This should do very well in the challenge.', '2004-02-28 21:03:52.000000', NULL, 1),
(603081, 61834, 6349, '<td valign="top">Great shot.  Good colors although I think the gold is a bit overpowering.</td>', 'Great shot.  Good colors although I think the gold is a bit overpowering.', '2004-02-28 21:04:59.000000', NULL, 1),
(603082, 60956, 6349, '<td valign="top">Very nice.  Good contrast and desaturation leaving the gold.  Very nice lines and composition.</td>', 'Very nice.  Good contrast and desaturation leaving the gold.  Very nice lines and composition.', '2004-02-28 21:06:03.000000', NULL, 1),
(603084, 61587, 11895, '<td valign="top">by far the best of the many TP entries, you did make the mundane look extraordinary</td>', 'by far the best of the many TP entries, you did make the mundane look extraordinary', '2004-02-28 21:06:32.000000', NULL, 1),
(603085, 61814, 4321, '<td valign="top">This is lovely. I really like the texture, the lighting and the color</td>', 'This is lovely. I really like the texture, the lighting and the color', '2004-02-28 21:06:55.000000', NULL, 1),
(603086, 61751, 4321, '<td valign="top">Clever idea and great colors</td>', 'Clever idea and great colors', '2004-02-28 21:08:08.000000', NULL, 1),
(603087, 61666, 6349, '<td valign="top">you must teach us all how to make these.  10</td>', 'you must teach us all how to make these.  10', '2004-02-28 21:09:30.000000', NULL, 1),
(603092, 61838, 6349, '<td valign="top">hahaha.  look at Ron!</td>', 'hahaha.  look at Ron!', '2004-02-28 21:15:39.000000', NULL, 1),
(603094, 61751, 6349, '<td valign="top">Awesome.  10</td>', 'Awesome.  10', '2004-02-28 21:19:33.000000', NULL, 1),
(603100, 61659, 10084, '<td valign="top">Very graphic image of the shadow.  The very white background really helps to make the bold image of the shadow opo out of the shot. Can''t help but think that a horizontal crop would look better. "9"</td>', 'Very graphic image of the shadow.  The very white background really helps to make the bold image of the shadow opo out of the shot. Can''t help but think that a horizontal crop would look better. "9"', '2004-02-28 21:26:02.000000', NULL, 1),
(603101, 61771, 10084, '<td valign="top">The only color being the green of the peas really makes your eyes focus on them. I think this is what makes this shot very interesting. I like the shadows that you have on the fork and the peas, but the shadow on the top left is a bit distracting.  I can see something like this hanging in a person''s kitchen or a restaurant. "8"</td>', 'The only color being the green of the peas really makes your eyes focus on them. I think this is what makes this shot very interesting. I like the shadows that you have on the fork and the peas, but the shadow on the top left is a bit distracting.  I can see something like this hanging in a person''s kitchen or a restaurant. "8"', '2004-02-28 21:29:03.000000', NULL, 1),
(603132, 61758, 11769, '<td valign="top">A lovely picture of a lovely industrial plant. Like the composition and smoke and clouds.</td>', 'A lovely picture of a lovely industrial plant. Like the composition and smoke and clouds.', '2004-02-28 23:13:00.000000', NULL, 1),
(603134, 61481, 11769, '<td valign="top">Nice comp and color. Good work</td>', 'Nice comp and color. Good work', '2004-02-28 23:14:37.000000', NULL, 1),
(603135, 61377, 11769, '<td valign="top">Wonderful abstract and one of my favorites.</td>', 'Wonderful abstract and one of my favorites.', '2004-02-28 23:15:38.000000', NULL, 1),
(603136, 61333, 11769, '<td valign="top">I like the light. Only comment is I like.</td>', 'I like the light. Only comment is I like.', '2004-02-28 23:18:10.000000', NULL, 1),
(603138, 61859, 11769, '<td valign="top">A strange color for printer paper. Abstract?</td>', 'A strange color for printer paper. Abstract?', '2004-02-28 23:19:29.000000', NULL, 1),
(603140, 61417, 11769, '<td valign="top">After your drunk? The picture escapes me. Sorry</td>', 'After your drunk? The picture escapes me. Sorry', '2004-02-28 23:20:48.000000', NULL, 1),
(603141, 61529, 11769, '<td valign="top">HAHAHAHA. Yes they are typically mundane. And this is I suppose extraordinary?</td>', 'HAHAHAHA. Yes they are typically mundane. And this is I suppose extraordinary?', '2004-02-28 23:22:52.000000', NULL, 1),
(603144, 61814, 11769, '<td valign="top">Nice fence boards. Overall very good. Im moving my score up</td>', 'Nice fence boards. Overall very good. Im moving my score up', '2004-02-28 23:24:25.000000', NULL, 1),
(603145, 61589, 11769, '<td valign="top">If only that was a pipe sticking out of Fluffy Clouds mouth. Then this would have been beyond extraordinary. Very funny guy. Love it.</td>', 'If only that was a pipe sticking out of Fluffy Clouds mouth. Then this would have been beyond extraordinary. Very funny guy. Love it.', '2004-02-28 23:26:56.000000', NULL, 1),
(603161, 61814, 12253, '<td valign="top">Nice shot with strong abstract qualities!</td>', 'Nice shot with strong abstract qualities!', '2004-02-29 00:06:07.000000', NULL, 1),
(603164, 61230, 5822, '<td valign="top">Perfect! Simple and very effective.  Love the high key and how it makes the red heart stand out. Well done.</td>', 'Perfect! Simple and very effective.  Love the high key and how it makes the red heart stand out. Well done.', '2004-02-29 00:09:39.000000', NULL, 1),
(603168, 61686, 10809, '<td valign="top">Kingston :)</td>', 'Kingston :)', '2004-02-29 00:33:43.000000', NULL, 1),
(603174, 60944, 8891, '<td valign="top">like the red, purple, gold color combo very much and very good composition. I like the patterning of the negative DOF of the two blaces crossing the others behine. but my eyes and my brain are not accepting their near invisibility or their thickness at their bright points. very nice and very good for this challenge.</td>', 'like the red, purple, gold color combo very much and very good composition. I like the patterning of the negative DOF of the two blaces crossing the others behine. but my eyes and my brain are not accepting their near invisibility or their thickness at their bright points. very nice and very good for this challenge.', '2004-02-29 01:01:05.000000', NULL, 1),
(603176, 61834, 8891, '<td valign="top">nice colors and detail, very good composition though the brush could have been a bit more angled downward. the item is mundane and might have been made more extraordinary by closing in further  and not making it so evident as to what it is.</td>', 'nice colors and detail, very good composition though the brush could have been a bit more angled downward. the item is mundane and might have been made more extraordinary by closing in further  and not making it so evident as to what it is.', '2004-02-29 01:03:41.000000', NULL, 1),
(603177, 61730, 8891, '<td valign="top">very nice exposure but the colors might have been bumped up a bit. the rock and the grass and other vegetation  along with the reddish rail provide nice texture contrasts but it all still looks pretty mundane to me.</td>', 'very nice exposure but the colors might have been bumped up a bit. the rock and the grass and other vegetation  along with the reddish rail provide nice texture contrasts but it all still looks pretty mundane to me.', '2004-02-29 01:05:37.000000', NULL, 1),
(603182, 61518, 8891, '<td valign="top">very nice....the eye shadow person might want to look at this to see what  I might have had in mind for that shot.....the detail on the pen is very good and the lighting excellent.  Very much like the composition and the pen tip looks great against the tiem in the DOF with the corresponding shining gold on its labe. Well lit.</td>', 'very nice....the eye shadow person might want to look at this to see what  I might have had in mind for that shot.....the detail on the pen is very good and the lighting excellent.  Very much like the composition and the pen tip looks great against the tiem in the DOF with the corresponding shining gold on its labe. Well lit.', '2004-02-29 01:09:20.000000', NULL, 1),
(603183, 61782, 8891, '<td valign="top">Yup, that''s what it is. the focus is rather soft on the flaps. the lighting is very good. the composition is static because of the centre placement of the subject in the frame.  The subject still looks like a plain old ordinary storage box.</td>', 'Yup, that''s what it is. the focus is rather soft on the flaps. the lighting is very good. the composition is static because of the centre placement of the subject in the frame.  The subject still looks like a plain old ordinary storage box.', '2004-02-29 01:12:12.000000', NULL, 1),
(603186, 61734, 8891, '<td valign="top">many time pieces might look mundance but this does not. like the composition but the focus and shadow on the hour hand are blending too much together due to the lack of focus and possibly the tone chosen. I might have shot down and up to get a different perspective of both hands and the clock face.</td>', 'many time pieces might look mundance but this does not. like the composition but the focus and shadow on the hour hand are blending too much together due to the lack of focus and possibly the tone chosen. I might have shot down and up to get a different perspective of both hands and the clock face.', '2004-02-29 01:15:35.000000', NULL, 1),
(603210, 61333, 16095, '<td valign="top">this is really great work.   a little distracted by dark blob on right.</td>', 'this is really great work.   a little distracted by dark blob on right.', '2004-02-29 01:38:44.000000', NULL, 1),
