INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(603572, 61843, 15330, '<td valign="top">I like all of the diagonal lines in the photo. The clouds , and blue in the background is also very nice. You should have probobly gotten a little closer to the tower, and closer to the ground, this would make the tower look bigger. Overall, I like it very much.</td>', 'I like all of the diagonal lines in the photo. The clouds , and blue in the background is also very nice. You should have probobly gotten a little closer to the tower, and closer to the ground, this would make the tower look bigger. Overall, I like it very much.', '2004-02-29 16:38:06.000000', NULL, 1),
(603575, 61834, 15330, '<td valign="top">The DOF is nice, lets me focus on one portion of the photo. I also like all of the colors. You should have probobly tried to compose it a little differently, so that the brush tip isn''t in the middle of the photo.</td>', 'The DOF is nice, lets me focus on one portion of the photo. I also like all of the colors. You should have probobly tried to compose it a little differently, so that the brush tip isn''t in the middle of the photo.', '2004-02-29 16:39:57.000000', NULL, 1),
(603576, 61386, 8891, '<td valign="top">Excellent....looks like a glass in a glass in a glas kaliedscope of the surrounding batteries....I might have done two things with this, turn the batteries more one way or the other to cover the name up and lessedn the lamp reflection in the glass. Like that innermost eye very much!</td>', 'Excellent....looks like a glass in a glass in a glas kaliedscope of the surrounding batteries....I might have done two things with this, turn the batteries more one way or the other to cover the name up and lessedn the lamp reflection in the glass. Like that innermost eye very much!', '2004-02-29 16:41:14.000000', NULL, 1),
(603577, 61751, 15330, '<td valign="top">Great job of being creative, so many entries are so similar, yours stands out. This also fits the subject very well, rubber bands are very ordinary. I think you should''ve used a smaller DOF, or somehow stopped the viewers eyes from moving up, and off the page.</td>', 'Great job of being creative, so many entries are so similar, yours stands out. This also fits the subject very well, rubber bands are very ordinary. I think you should''ve used a smaller DOF, or somehow stopped the viewers eyes from moving up, and off the page.', '2004-02-29 16:42:24.000000', NULL, 1),
(603579, 61840, 8891, '<td valign="top">Talons are hardly mundane unless you live or work in an aviary they are not commonplace at all.  Regardless you have taken this talon and might look more extraordinary than it is already with the excellent texture contrasts, detail and the superb shadow.  Ribbon please.</td>', 'Talons are hardly mundane unless you live or work in an aviary they are not commonplace at all.  Regardless you have taken this talon and might look more extraordinary than it is already with the excellent texture contrasts, detail and the superb shadow.  Ribbon please.', '2004-02-29 16:42:59.000000', NULL, 1),
(603581, 61719, 15330, '<td valign="top">I like the photo, but can''t figure out what this is. It would have helped to take this at a different time, or a different day. The sky is just too bright, and blown out in the top left corner.</td>', 'I like the photo, but can''t figure out what this is. It would have helped to take this at a different time, or a different day. The sky is just too bright, and blown out in the top left corner.', '2004-02-29 16:44:06.000000', NULL, 1),
