(604057, 60898, 6405, '<td valign="top">Cool distortion ,10 !</td>', 'Cool distortion ,10 !', '2004-02-29 23:56:42.000000', NULL, 1),
(604060, 61840, 70, '<td valign="top">Pssht...didn''t even make it until March. :P</td>', 'Pssht...didn''t even make it until March. :P', '2004-03-01 00:02:17.000000', NULL, 0),
(604070, 61652, 14499, '<td valign="top">Considering the amount of effort I put into this one it was no way near the reaction I thought it would get. Obviously too much Photo Shopping doesn''t go down well.<br/> <br/>I will know better next time :)</td>', 'Considering the amount of effort I put into this one it was no way near the reaction I thought it would get. Obviously too much Photo Shopping doesn''t go down well. I will know better next time :)', '2004-03-01 00:06:57.000000', NULL, 0),
(604073, 61840, 4258, '<td valign="top">I wonder how a composition with as much of the talon showing as in the shadow would have looked - would that make the photo bland or better...</td>', 'I wonder how a composition with as much of the talon showing as in the shadow would have looked - would that make the photo bland or better...', '2004-03-01 00:09:14.000000', NULL, 0),
(604075, 60897, 16301, '<td valign="top">Thanks to everyone who commented, I really appriciate it!<br/><br/><br/><i>Message edited by author 2004-03-03 09:10:11.</i></td>', 'Thanks to everyone who commented, I really appriciate it!', '2004-03-01 00:09:53.000000', '2004-03-03 09:10:11.000000', 0),
