(604084, 61550, 14499, '<td valign="top">Great shot... well done on 7th</td>', 'Great shot... well done on 7th', '2004-03-01 00:15:03.000000', NULL, 0),
(604087, 61809, 10084, '<td valign="top">Very nice shot. This was one the best fork photo in the challenge. Love the graphic nature of the shot.Excellent textures in the background. The spotlights really add to the great composition.</td>', 'Very nice shot. This was one the best fork photo in the challenge. Love the graphic nature of the shot.Excellent textures in the background. The spotlights really add to the great composition.', '2004-03-01 00:16:33.000000', NULL, 0),
(604089, 61806, 11800, '<td valign="top">Good job. Should have figured out the colored paper part and the mirror. This was really set up nicely.</td>', 'Good job. Should have figured out the colored paper part and the mirror. This was really set up nicely.', '2004-03-01 00:18:04.000000', NULL, 0),
(604094, 61646, 16430, '<td valign="top">Thanks to everyone for your votes and comments.</td>', 'Thanks to everyone for your votes and comments.', '2004-03-01 00:19:33.000000', NULL, 0),
