(604103, 61740, 8891, '<td valign="top">See I thought this was you, jacko! Almost left it in the comment. Really thought this would do better.</td>', 'See I thought this was you, jacko! Almost left it in the comment. Really thought this would do better.', '2004-03-01 00:24:29.000000', NULL, 0),
(604106, 61740, 772, '<td valign="top">This is like $5 US.</td>', 'This is like $5 US.', '2004-03-01 00:25:19.000000', NULL, 0),
(604113, 61666, 6349, '<td valign="top">I thought this was going to ribbon.  Awesome job.  Got a tutorial on how to make those?</td>', 'I thought this was going to ribbon.  Awesome job.  Got a tutorial on how to make those?', '2004-03-01 00:31:46.000000', NULL, 0),
(604115, 61592, 6349, '<td valign="top">I thought this would do much better.  Going in my favorites.  Keep up the good work.</td>', 'I thought this would do much better.  Going in my favorites.  Keep up the good work.', '2004-03-01 00:32:42.000000', NULL, 0),
(604116, 61751, 6349, '<td valign="top">Congrats Eddy.  Knew this was a ribbon the second I saw it.</td>', 'Congrats Eddy.  Knew this was a ribbon the second I saw it.', '2004-03-01 00:33:24.000000', NULL, 0),
(604117, 61646, 15305, '<td valign="top">I can''t believe it!!!  I really thought this one was going into the top 10...  Anyway, I''ve seen your pictures and I really like your style. I usually vote 10 on them!! Congratulations on great photographs ant thanks for sharing them with us.</td>', 'I can''t believe it!!!  I really thought this one was going into the top 10...  Anyway, I''ve seen your pictures and I really like your style. I usually vote 10 on them!! Congratulations on great photographs ant thanks for sharing them with us.', '2004-03-01 00:34:05.000000', NULL, 0),
(604118, 61711, 6349, '<td valign="top">You beat me by 1 place!  This was one of my favorites for the challenge.  Going in my favorites.</td>', 'You beat me by 1 place!  This was one of my favorites for the challenge.  Going in my favorites.', '2004-03-01 00:34:09.000000', NULL, 0),
(604121, 61686, 11078, '<td valign="top">congratulations on the ribbon<br/>A great photo</td>', 'congratulations on the ribbonA great photo', '2004-03-01 00:45:19.000000', NULL, 0),
