(604128, 61719, 15407, '<td valign="top">A well deseved win! It got my top vote !</td>', 'A well deseved win! It got my top vote !', '2004-03-01 01:05:04.000000', NULL, 0),
(604129, 61557, 9906, '<td valign="top">I should have known that this was you JJ.  Love the simplicity of subject and tonality of this shot.  You have my vote for underrated shot of the challenge!<br/> <br/>Yours<br/>TC</td>', 'I should have known that this was you JJ.  Love the simplicity of subject and tonality of this shot.  You have my vote for underrated shot of the challenge! YoursTC', '2004-03-01 01:07:00.000000', NULL, 0),
(604137, 61537, 10055, '<td valign="top">Thank you folks for the comments and voting. I agree, the blinds are a bit distracting. I wasn''t really think about that when I shot it. I was seeing them as a way to enhance a mundane object. I could of tilt more to the right to balance the photo out now that I see it. Perhaps I shot at that angle due to the lighting from outside. I can''t remember. However, It was a nice design attempt to make something mundane look interesting. I have learned a lot from this one. This shot looks better after I had made it more into and abstract art piece in Photoshop. Looks much better that a normal photo.</td>', 'Thank you folks for the comments and voting. I agree, the blinds are a bit distracting. I wasn''t really think about that when I shot it. I was seeing them as a way to enhance a mundane object. I could of tilt more to the right to balance the photo out now that I see it. Perhaps I shot at that angle due to the lighting from outside. I can''t remember. However, It was a nice design attempt to make something mundane look interesting. I have learned a lot from this one. This shot looks better after I had made it more into and abstract art piece in Photoshop. Looks much better that a normal photo.', '2004-03-01 01:28:39.000000', NULL, 0),
(604217, 61719, 14398, '<td valign="top">ah ha! i knew that was in birmingham! nice building that is.</td>', 'ah ha! i knew that was in birmingham! nice building that is.', '2004-03-01 02:42:36.000000', NULL, 0),
(604233, 61771, 16636, '<td valign="top">Thanks for all the comments, much appreciated.<br/></td>', 'Thanks for all the comments, much appreciated.', '2004-03-01 03:17:35.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(604234, 61095, 245, '<td valign="top">Thanks everyone for the votes and comments, 8th place is a great way to start competing here again! You can''t even imagine how thrilled I am! :)<br/><br/><i>Message edited by author 2004-03-01 03:32:58.</i></td>', 'Thanks everyone for the votes and comments, 8th place is a great way to start competing here again! You can''t even imagine how thrilled I am! :)', '2004-03-01 03:19:23.000000', '2004-03-01 03:32:58.000000', 0),
(604276, 61592, 14603, '<td valign="top">Expected to see this amongst the top ten images.<br/> <br/>Good work Terry.</td>', 'Expected to see this amongst the top ten images. Good work Terry.', '2004-03-01 05:44:00.000000', NULL, 0),
(604297, 61708, 13152, '<td valign="top">Thanks for all of the comments. About 12 years ago I did design work for a large estate agent and noticed that they threw away lots of keys. I asked them to put  them aside for me, and ended up with a sack of about 500 keys. I thought that they might be useful some day :-)</td>', 'Thanks for all of the comments. About 12 years ago I did design work for a large estate agent and noticed that they threw away lots of keys. I asked them to put  them aside for me, and ended up with a sack of about 500 keys. I thought that they might be useful some day :-)', '2004-03-01 07:25:37.000000', NULL, 0),
(604302, 61751, 806, '<td valign="top">Brilliant, Eddy! great work!</td>', 'Brilliant, Eddy! great work!', '2004-03-01 07:33:16.000000', NULL, 0),
(604318, 61751, 5728, '<td valign="top">Congrats Eddy, way to go!</td>', 'Congrats Eddy, way to go!', '2004-03-01 08:03:12.000000', NULL, 0),
(604375, 61751, 8159, '<td valign="top"><b>Thanks for all the comments everyone!</b> <br/> <br/>One of the hardest parts about this entry was coming up with a title for the shot. I submitted it with something "mundane" like "Keep on rollin''" (or something equally lame) and at the last minute, the much-better title "Growth Opportunity" just hit me.<br/> <br/>For anyone interested, here is an "out-take" that shows an alternative composition I was considering:<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=62851" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/8159/thumb/62851.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/8159/thumb/62851.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/8159/thumb/62851.jpg"/></a></td>', 'Thanks for all the comments everyone!  One of the hardest parts about this entry was coming up with a title for the shot. I submitted it with something "mundane" like "Keep on rollin''" (or something equally lame) and at the last minute, the much-better title "Growth Opportunity" just hit me. For anyone interested, here is an "out-take" that shows an alternative composition I was considering:', '2004-03-01 09:47:06.000000', NULL, 0),
(604381, 61740, 4285, '<td valign="top">Great macro. I think you would have done better shooting an American dime.......with exchange rate and all.</td>', 'Great macro. I think you would have done better shooting an American dime.......with exchange rate and all.', '2004-03-01 09:56:05.000000', NULL, 0),
(604438, 61731, 1934, '<td valign="top">Frábært að sjá þig aftur í efstu sætunum! Good work as always!<br/> <br/>kveðja, aui sveitungur</td>', 'Frábært að sjá þig aftur í efstu sætunum! Good work as always! kveðja, aui sveitungur', '2004-03-01 11:16:13.000000', NULL, 0),
(604464, 61796, 3599, '<td valign="top">_<br/><br/><i>Message edited by author 2005-04-14 13:13:32.</i></td>', '_', '2004-03-01 11:52:50.000000', '2005-04-14 14:13:32.000000', 0),
(604498, 61809, 12268, '<td valign="top">Thanks everyone for your insightful &amp; kind commnets. I kinda got luck y wiht this shot &amp; ended up with something that was nice &amp; fit the challenge well. This was ahard challenge for bc I couldn'';t think of somthing good to do. I had done a fork &amp; knife shot before &amp; it did just alright so I was a bit apprehensive of doing yet another fork shot. All in all I think I did pretty well &amp; am very please with the shot.<br/>Thanks again everyone!</td>', 'Thanks everyone for your insightful & kind commnets. I kinda got luck y wiht this shot & ended up with something that was nice & fit the challenge well. This was ahard challenge for bc I couldn'';t think of somthing good to do. I had done a fork & knife shot before & it did just alright so I was a bit apprehensive of doing yet another fork shot. All in all I think I did pretty well & am very please with the shot.Thanks again everyone!', '2004-03-01 12:23:04.000000', NULL, 0),
(604558, 61645, 9581, '<td valign="top">Would have loved to see this shot do better! I think I gave it a 9 should had more 10s......Some of my homemade bird was made using macaw feathers I guess thats why I like yours so much! <a href="//www.dpchallenge.com/image.php?IMAGE_ID=61750" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/192/thumb/61750.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/192/thumb/61750.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/192/thumb/61750.jpg"/></a></td>', 'Would have loved to see this shot do better! I think I gave it a 9 should had more 10s......Some of my homemade bird was made using macaw feathers I guess thats why I like yours so much! ', '2004-03-01 13:13:15.000000', NULL, 0),
(604648, 61659, 10785, '<td valign="top">I like trying to recreate shots other people have done to improve my skills. A lot of people found this original, but this has actually been done here on DPC before as well...<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=49704" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_challenge/165/thumb/49704.jpg'', strrpos(''//images.dpchallenge.com/images_challenge/165/thumb/49704.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_challenge/165/thumb/49704.jpg"/></a></td>', 'I like trying to recreate shots other people have done to improve my skills. A lot of people found this original, but this has actually been done here on DPC before as well... ', '2004-03-01 14:46:51.000000', NULL, 0),
(604684, 61751, 14773, '<td valign="top">Very nice shot [and I saw the one white band]..even if it''s not your own original concept, I still like it.</td>', 'Very nice shot [and I saw the one white band]..even if it''s not your own original concept, I still like it.', '2004-03-01 15:25:32.000000', NULL, 0),
(604706, 61529, 772, '<td valign="top">Greetings from the critique club :)<br/> <br/>Without the title, I would not know what I''m looking at in this photo. With the title, the photo meets the challenge.  I think you did a nice job of using selective depth of field to isolate a small portion of the image for ''focus''.  The texture is somewhat interesting.  The non-literal approach to your subject usually works fairly well also.  This photo didn''t score particularly well, and thats probably because there is nothing particularly interesting to look at in the image.  I didn''t care much for this challenge topic because I knew this aspect would be a problem...<br/> <br/>Keep up the good work :)<br/> <br/>John Setzler<br/></td>', 'Greetings from the critique club :) Without the title, I would not know what I''m looking at in this photo. With the title, the photo meets the challenge.  I think you did a nice job of using selective depth of field to isolate a small portion of the image for ''focus''.  The texture is somewhat interesting.  The non-literal approach to your subject usually works fairly well also.  This photo didn''t score particularly well, and thats probably because there is nothing particularly interesting to look at in the image.  I didn''t care much for this challenge topic because I knew this aspect would be a problem... Keep up the good work :) John Setzler', '2004-03-01 15:36:33.000000', NULL, 0),
