(605342, 61751, 17701, '<td valign="top">Very inspiring as it encourages making intriguing compositions from cheaply obtainable materials.</td>', 'Very inspiring as it encourages making intriguing compositions from cheaply obtainable materials.', '2004-03-02 04:23:37.000000', NULL, 0),
